// matheditorui.js - отвечает за кнопку на панели и модальное окно для ввода формулы
import { ButtonView, Plugin } from 'ckeditor5';
import MathFormView from './matheditorview';
import MathEditorModal from './matheditormodal';

export default class MathEditorUI extends Plugin {
    init() {
        const editor = this.editor;

        // Создаём модалку
        this._modal = new MathEditorModal(editor.locale);
        this._modal.on('close', () => {
            // Сброс состояния при закрытии модалки.
            // formView больше не сбрасываем - он создаётся заново при каждом открытии.
            this._editingMathBlock = null;
            this.formView = null;
            this.editor.editing.view.focus();
        });

        // formView здесь НЕ создаём - он создаётся в _showUI()
        this.formView = null;
        this._editingMathBlock = null;

        // Событие из editing-плагина (двойной клик по формуле)
        editor.on('mathEditor:editFormula', (event, data) => {
            this.openEditDialog(data.modelElement, data.latex);
        });

        // Кнопка на тулбаре
        editor.ui.componentFactory.add('matheditor', () => {
            const button = new ButtonView();
            const command = editor.commands.get('insertMath');

            button.set({
                label: 'Вставить формулу',
                icon: `<svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round">
                        <path d="M3 12h3.28a1 1 0 0 1 .948.684l2.298 7.934a.5.5 0 0 0 .96-.044L13.82 4.771A1 1 0 0 1 14.792 4H21" fill="none" />
                    </svg>`,
                tooltip: true
            });

            button.bind('isEnabled').to(command, 'isEnabled');

            this._mathButton = button;

            button.on('execute', () => {
                // 🔑 Защита: не открываем, если редактор только для чтения
                if (this.editor.isReadOnly) return;

                const selectedMathBlock = this._getSelectedMathBlock();

                if (selectedMathBlock) {
                    // Редактирование выделенной формулы
                    const latex = selectedMathBlock.getAttribute('latex');
                    this.openEditDialog(selectedMathBlock, latex);
                } else if (this._modal.isVisible()) {
                    // Закрываем открытую модалку
                    this._hideUI();
                } else {
                    // Вставка новой формулы
                    this._editingMathBlock = null;
                    this._showUI();
                }
            });

            return button;
        });

        this._setupSelectionObserver();
    }

    _setupSelectionObserver() {
        const editor = this.editor;
        const model = editor.model;

        const updateButtonState = () => {
            if (!this._mathButton) return;

            const selectedMathBlock = this._getSelectedMathBlock();
            if (selectedMathBlock) {
                this._mathButton.set({
                    label: 'Редактировать формулу',
                    tooltip: 'Редактировать выделенную формулу'
                });
            } else {
                this._mathButton.set({
                    label: 'Вставить формулу',
                    tooltip: 'Вставить новую формулу'
                });
            }
        };

        model.document.selection.on('change', updateButtonState);
        updateButtonState();
    }

    _getSelectedMathBlock() {
        const editor = this.editor;
        const selection = editor.model.document.selection;

        const selectedElement = selection.getSelectedElement();
        if (selectedElement && selectedElement.is('element', 'mathBlock')) {
            return selectedElement;
        }

        const position = selection.getFirstPosition();
        if (position && position.parent && position.parent.is('element', 'mathBlock')) {
            return position.parent;
        }

        return null;
    }

    openEditDialog(modelElement, latex) {
        if (this.editor.isReadOnly) return;

        this._editingMathBlock = modelElement;

        // Если модалка уже открыта - сначала закрываем, потом открываем заново с новым значением
        if (this._modal.isVisible()) {
            this._modal.hide();
            // hide() асинхронный (ждёт анимацию), поэтому открываем чуть позже
            setTimeout(() => this._showUI(latex), 200);
        } else {
            this._showUI(latex);
        }
    }

    _createFormView() {
        const editor = this.editor;
        const formView = new MathFormView(editor.locale);

        formView.on('submit', () => {
            const { latex, html } = formView.getValue();

            if (this._editingMathBlock) {
                // Режим редактирования
                editor.fire('mathEditor:updateFormula', {
                    modelElement: this._editingMathBlock,
                    latex: latex,
                    html: html
                });
                this._editingMathBlock = null;
            } else {
                // Режим вставки
                editor.execute('insertMath', { latex, html });
            }

            this._hideUI();
        });

        formView.on('cancel', () => {
            this._editingMathBlock = null;
            this._hideUI();
        });

        return formView;
    }

    _showUI(latex = '') {
        if (this.editor.isReadOnly) return;
        if (this._modal.isVisible()) return;

        // Создаём НОВУЮ форму каждый раз — это обходит ошибку ui-view-render-already-rendered
        this.formView = this._createFormView();

        // Устанавливаем значение, если есть
        if (latex) {
            this.formView.setValue(latex);
        }

        // Показываем модалку с формой
        this._modal.show(this.formView);

        setTimeout(() => {
            this.formView.focus();
        }, 100);
    }

    _hideUI() {
        if (!this._modal.isVisible()) return;

        this._modal.hide();
    }
}