// matheditorcommand.js - команда для вставки новой формулы в документ
import { Command } from 'ckeditor5';

// Команда - это действие, которое можно выполнить в редакторе
// (например, вставить формулу, изменить текст и т.д.)
export default class MathEditorCommand extends Command {
    
    // Конструктор - вызывается при создании команды
    constructor(editor) {
        super(editor);
        // Убираем forceDisabled, так как это внутренний метод CKEditor
        // Вместо этого просто устанавливаем начальное состояние
        this.isEnabled = true;
    }
    
    // Метод execute вызывается, когда команду выполняют
    // options - объект с данными формулы { latex: "...", html: "..." }
    execute(options = {}) {
        const model = this.editor.model;
        const { latex, html } = options;

        // Все изменения в модели нужно делать внутри change()
        // Это гарантирует, что все операции будут записаны в историю для Undo/Redo
        model.change(writer => {
            // Создаём новый элемент модели - блок формулы
            // Сохраняем в него LaTeX код и HTML представление
            const mathBlock = writer.createElement('mathBlock', {
                latex: latex || '',
                html: html || ''
            });

            // Вставляем созданный блок в текущую позицию курсора
            model.insertContent(mathBlock, model.document.selection);
            
            // Перемещаем курсор после вставленной формулы
            // writer.createPositionAfter(mathBlock) создаёт позицию сразу после элемента
            writer.setSelection(writer.createPositionAfter(mathBlock));
        });
    }

    // Этот метод обновляет состояние команды (доступна/недоступна)
    // Вызывается автоматически при изменении редактора
    refresh() {
        const model = this.editor.model;
        const selection = model.document.selection;

        // Проверяем, что редактор не в режиме "только чтение"
        if (this.editor.isReadOnly) {
            this.isEnabled = false;
            return;
        }
        
        // Проверяем, можем ли мы вставить формулу в текущую позицию
        try {
            // Команда доступна, если курсор не внутри существующей формулы
            const isInMathBlock = selection.getFirstPosition()?.parent?.is('mathBlock');
            this.isEnabled = !isInMathBlock;
        } catch (error) {
            // Если произошла ошибка, команда всё равно доступна
            this.isEnabled = true;
        }
    }
}