import { CKEditor } from "@ckeditor/ckeditor5-react";
import { 
  ClassicEditor,
  Essentials,
  Paragraph,
  Bold,
  Italic,
  Table,
  TableToolbar,
  List,
  ListProperties,
  Indent,
  IndentBlock,
  BlockQuote,
  Alignment,
  CodeBlock
} from "ckeditor5"

import MathEditor from './plugins/insertMath/matheditor';
import ruTranslations from "ckeditor5/translations/ru.js";
import "ckeditor5/ckeditor5.css";
import "./Editor.css"

const Editor = ({
  value,
  onChange,
  pasteFromClipboard = true,
  ...props
}) => {

  return (
    <CKEditor
      editor={ClassicEditor}
      config={{
        licenseKey: "GPL",
        plugins: [
          MathEditor,
          Essentials,
          Paragraph,
          Bold,
          Italic,
          Table,
          TableToolbar,
          List,
          ListProperties,
          Indent,
          IndentBlock,
          BlockQuote,
          Alignment,
          CodeBlock
        ],
        toolbar: [
            'undo', 'redo', '|',
            'bold', 'italic', '|',
            "matheditor",
            'insertTable', 'bulletedList', 'numberedList', 'indent', 'outdent', '|',
            'blockQuote', 'alignment', '|',
            'codeBlock'
        ],
        translations: [ruTranslations]
      }}
      onReady={(editor) => {
        editor.editing.view.document.on("clipboardInput", (evt) => evt.stop())
      }}
      onChange={(_, editor) => {
        const editorData = editor.getData()
        onChange && onChange(editorData || null)
      }}
      data={value || ''}
      disabled={false}
      {...props}
    />
  );
};

export default Editor;
