import { Plugin } from 'ckeditor5';
import MathEditorEditing from './matheditorediting';
import MathEditorUI from './matheditorui';
import "./plugin.css"
import "katex/dist/katex.min.css"

// Главный класс плагина - это "диспетчер", который собирает вместе все части плагина
export default class MathEditor extends Plugin {
    // Возвращает уникальное имя плагина (нужно для CKEditor)
    static get pluginName() {
        return 'MathEditor';
    }

    // Говорит CKEditor, какие подмодули нужны для работы плагина
    // Editing - отвечает за хранение данных и логику
    // UI - отвечает за кнопки и окошки, которые видит пользователь
    static get requires() {
        return [MathEditorEditing, MathEditorUI];
    }
}