import { useContext, useEffect, useState } from "react"
import TestingsFilter from "../../components/shared/TestingsFilter"
import { useFetching } from "../../hooks/useFetching"
import TestingService from "../../api/TestingService"
import { AppContext } from "../../context"
import Button from "../../components/ui/Button/Button"
import Loader from "../../components/ui/Loader/Loader"
import Layout from "../../components/Layout"
import { formatDate } from "../../utils/date"
import { printElement } from "../../utils/print"

const FacultyPage = () => {
  const { showToast, employeeId } = useContext(AppContext)
  
  const [testings, setTestings] = useState([])
  const [testingsWithFilter, setTestingsWithFilter] = useState([])
  const [getTestingsForFaculty, isTestingsLoading] = useFetching(async () => {
    const response = await TestingService.getTestingsByEmployeeIdForFaculty(employeeId)
    if (response.status == 200) {
        setTestings(response.data)
        setTestingsWithFilter(response.data)
    }
  })

  const [activeTestingId, setActiveTestingId] = useState(null)
  const [statisticForPrint, setStatisticForPrint] = useState(null)
  const [getStatisticForPrint, isStatisticForPrintLoading] = useFetching(async (testingId) => {
    const response = await TestingService.getStatisticForPrint(testingId)
    if (response.status == 200) {
        setActiveTestingId(null)
        setStatisticForPrint(response.data)
    } else {
        showToast("error", response.data || "Ошибка при получении данных для распечатки ведомости")
    }
  })

  const handleFilterSubmit = (data) => {
    let newTestingFiltersData = testings

    if (data.deptId) {
      newTestingFiltersData = newTestingFiltersData.filter(t => t.departmentId == data.deptId)
    }

    if (data.examDateBefore) {
      const beforeDateTime = new Date(data.examDateBefore)
      newTestingFiltersData = newTestingFiltersData.filter(t => new Date(t.testingDate).setHours(0, 0, 0) >= beforeDateTime)
    }

    if (data.examDateAfter) {
      const afterDateTime = new Date(data.examDateAfter)
      newTestingFiltersData = newTestingFiltersData.filter(t => new Date(t.testingDate).setHours(0, 0, 0) <= afterDateTime)
    }

    setTestingsWithFilter(newTestingFiltersData)
  }

  const handlePrintStatistic = (testingId) => {
    setActiveTestingId(testingId)
    getStatisticForPrint(testingId)
  }

  useEffect(() => {
    getTestingsForFaculty(employeeId)
  }, [])

  useEffect(() => {
    if (statisticForPrint) {
        printElement(".statement")
        window.addEventListener("afterprint", () => setStatisticForPrint(null))
    }

    return () => {
        window.removeEventListener("afterprint", () => setStatisticForPrint(null))
    }
  }, [statisticForPrint])

  return (
    <Layout>
        <div className='container'>
            <div className="statement">
                <div className="statement__header statement-header">
                <div className="statement-header__data">
                    <span className='statement-header__data-item statement-header__data-item_study-year'><strong>Учебный год</strong></span>
                    <span className='statement-header__data-item statement-header__data-item_years'><strong>{statisticForPrint?.academicYear}</strong></span>
                    <span className='statement-header__data-item statement-header__data-item_season'>{statisticForPrint?.session}</span>
                </div>
                <div className="statement-header__captions">
                    <h1 className="statement-header__title"><strong>МИНИСТЕРСТВО НАУКИ И ВЫСШЕГО ОБРАЗОВАНИЯ</strong></h1>
                    <h2 className="statement-header__subtitle"><strong>Дагестанский государственный университет</strong></h2>
                </div>
                </div>
                <div className="statement__body statement-body">
                    <ul className="statement-body__list">
                        <li className="statement-body__item statement-info">
                        <p className='statement-info__name'><strong>Филиал:</strong></p>
                        <p className='statement-info__value'>{statisticForPrint?.filial}</p>
                        </li>
                        <li className="statement-body__item statement-info">
                        <p className='statement-info__name'><strong>Факультет/институт:</strong></p>
                        <p className='statement-info__value'>{statisticForPrint?.faculty}</p>
                        </li>
                        <li className="statement-body__item statement-info">
                        <p className='statement-info__name'><strong>Направление/специальность:</strong></p>
                        <p className='statement-info__value'>{statisticForPrint?.department}</p>
                        </li>
                        <li className="statement-body__item statement-info">
                        <p className='statement-info__name'><strong>Курс:</strong></p>
                        <p className='statement-info__value'>{statisticForPrint?.course}</p>
                        </li>
                        <li className="statement-body__item statement-info">
                        <p className='statement-info__name'><strong>Группа:</strong></p>
                        <p className='statement-info__value'>{statisticForPrint?.nGroup}</p>
                        </li>
                        <li className="statement-body__item statement-info">
                        <p className='statement-info__name'><strong>Дисциплина:</strong></p>
                        <p className='statement-info__value'>{statisticForPrint?.discipline}</p>
                        </li>
                        <li className="statement-body__item statement-info">
                        <p className='statement-info__name'><strong>ФИО экзаменатора и ассистента:</strong></p>
                        <p className='statement-info__value'>{statisticForPrint?.teachers.join(", ")}</p>
                        </li>
                        <li className="statement-body__item statement-info">
                        <p className='statement-info__name'><strong>Дата проведения:</strong></p>
                        <p className='statement-info__value'>{formatDate(new Date(statisticForPrint?.testingDate))}</p>
                        </li>
                    </ul>
                </div>
                <div className="statement__table">
                    <table>
                        <thead>
                        <tr>
                            <th>№<br/>п/п</th>
                            <th>ФИО</th>
                            <th>Баллы</th>
                            <th>Начало</th>
                            <th>Конец</th>
                        </tr>
                        </thead>
                        <tbody>
                        {
                            statisticForPrint?.statisticsStudentForPrints.map((student, idx) => (
                            <tr key={idx}>
                                <td>{idx + 1}</td>
                                <td>{student.fio}</td>
                                <td>{student.totalScore ? Math.round(student.totalScore) : " - "}</td>
                                <td>{student.beginDate ? formatDate(new Date(student.beginDate)) : " - "}</td>
                                <td>{student.endDate ? formatDate(new Date(student.endDate)) : " - "}</td>
                            </tr>
                            ))
                        }
                        </tbody>
                    </table>
                </div>
            </div>
            <div className="testings">
                <div className="testings__filter">
                    <TestingsFilter onSubmit={handleFilterSubmit} onReset={() => setTestingsWithFilter(testings)} />
                </div>
                <h1 className="testings__title title">Тестирования</h1>
                <div className="testings__table">
                    {
                        isTestingsLoading
                        ? <Loader text="Загрузка тестирований" />
                        :
                            <table>
                                <thead>
                                    <tr>
                                        <th>Направление</th>
                                        <th>Курс</th>
                                        <th>Группа</th>
                                        <th>Дисциплина</th>
                                        <th>Дата проведения</th>
                                        <th>Статус</th>
                                        <th>Действие</th>
                                    </tr>
                                </thead>
                                <tbody>
                                    {
                                        testingsWithFilter.map((testing, index) => (
                                            <tr key={index}>
                                                <td>{testing.department}</td>
                                                <td>{testing.course}</td>
                                                <td>{testing.nGroup}</td>
                                                <td>{testing.disciplineName}</td>
                                                <td>{formatDate(new Date(testing.testingDate))}</td>
                                                <td>{testing.testingStatus == "Finished"
                                                    ? "Тестирование окончено, ожидается проверка преподавателем. Длится до окончания сотрудником"
                                                : "Проверено"}</td>
                                                <td>
                                                    {
                                                        testing.testingStatus == "Checked"
                                                        &&
                                                        <Button disabled={isStatisticForPrintLoading} onClick={() => handlePrintStatistic(testing.testingId)}>
                                                            {(isStatisticForPrintLoading && activeTestingId == testing.testingId)
                                                                ? <Loader text="Загрузка данных" /> 
                                                                : "Распечатать ведомость"
                                                            }
                                                        </Button>
                                                    }

                                                </td>
                                            </tr>
                                        ))
                                    }
                                </tbody>
                            </table>    
                    }
                </div>
            </div>
        </div>
    </Layout>
  )
}

export default FacultyPage