import { useState, useEffect, useContext } from 'react'
import { Link, useNavigate } from 'react-router-dom'
import { useLocation } from 'react-router-dom'
import QuestionTypeService from "../../api/QuestionTypeService"
import QuestionService from '../../api/QuestionService'
import { useFetching } from '../../hooks/useFetching'
import Loader from "../../components/ui/Loader/Loader"
import UpdateQuestionsPreview from '../../components/uko/UpdateQuestionsPreview'
import Layout from '../../components/Layout'
import { AppContext } from '../../context'
import Button from '../../components/ui/Button/Button'


const UpdateTestingFirstStep = () => {
    const location = useLocation()
    const {testing, successCreateRedirectUrl} = location.state
    const { showToast } = useContext(AppContext)
    const redirect = useNavigate()

    const [questionsForUpdate, setQuestionsForUpdate] = useState([])
    const [getQuestionsBankByTestingId, isQuestionsLoading] = useFetching(async (testingId) => {
        const response = await QuestionService.getQuestionsByTestingId(testingId)
        if (response.status == 200) {
            setQuestionsForUpdate(response.data)  
        }
    })

    const [questionTypes, setQuestionTypes] = useState([])
    const [getQuestionTypes, isTypesLoading] = useFetching(async () => {
        const response = await QuestionTypeService.getQuestionTypes()
        if (response.status == 200) {
            setQuestionTypes(response.data)
        }
    })

    const validateQuestionNumberFour = (questions) => {
        const res = []
        
        for (let question of questions) {
            const fixedElements = question.item.answerVariants.filter(v => v.isFixedElement)
            const notFixedElements = question.item.answerVariants.filter(v => !v.isFixedElement)
            const isValid = fixedElements.every(e => 
                notFixedElements.findLast(q => q.numberAnswerVariant == e.numberAnswerVariant && !q.isFixedElement)
            )
            if (!isValid) {
                res.push(question.index + 1)
            }
        }

        return res
    } 

    const handleMoveToSecondStep = () => {
        const questionNumberFourTypeId = questionTypes.find(q => q.questionTypeName == "№вопрос4").id
        const questionsNumberFour = questionsForUpdate.reduce((acc, q, idx) => {
            if (q.questionTypeId == questionNumberFourTypeId) {
                acc.push({ index: idx, item: q });
            }
            return acc;
        }, [])
        const invalidQuestionNumbers = validateQuestionNumberFour(questionsNumberFour)
        if (invalidQuestionNumbers.length) {
            showToast("error", `Не все соответствия были установлены в следующих вопросах: ${invalidQuestionNumbers.join(", ")}`)
        } else {
            redirect("/update/2", {
                state: {
                    testing, 
                    questions: questionsForUpdate, 
                    successCreateRedirectUrl
                }
            })
        }
    }

    useEffect(() => {
        getQuestionsBankByTestingId(testing.testingId)
        getQuestionTypes()
    }, [])

    return (
        <Layout>
            <div className='update-testing'>
                <div className="container">
                    <Link className='update-testing__back btn btn_secondary' to={-1}>Назад</Link>
                    <h1 className='update-testing__title title'>Шаг 1. Проверьте правильность заполнения данных</h1>
                    { 
                        (isQuestionsLoading && isTypesLoading) 
                        ? <Loader text="Идет загрузка банка тестов" />
                        : <UpdateQuestionsPreview onChange={setQuestionsForUpdate} questions={questionsForUpdate} questionTypes={questionTypes} /> 
                    }
                    <Button className="update-testing__next" onClick={handleMoveToSecondStep}>Перейти на следующий шаг</Button>
                </div>
            </div>
        </Layout>
    )
}

export default UpdateTestingFirstStep