// matheditorview.js - форма для ввода формулы с mathlive
import {
    ButtonView,
    View,
    submitHandler
} from 'ckeditor5';
import { MathfieldElement } from 'mathlive';
import katex from 'katex';
import { MATH_CATEGORIES } from './mathbuttons';

export default class MathFormView extends View {
    constructor(locale) {
        super(locale);

        this.mathInputView = this._createMathInputView(this.locale);

        // Кнопка submit — только текст, без иконки
        this.saveButtonView = new ButtonView(locale);
        this.saveButtonView.set({
            label: 'Вставить',
            withText: true,
            tooltip: false,
            class: 'ck-button-action ck-rounded-corners'
        });
        this.saveButtonView.type = 'submit';

        this.actionsView = new View(locale);
        this.actionsView.setTemplate({
            tag: 'div',
            attributes: { class: ['ck-math-form-actions'] },
            children: [ this.saveButtonView ]
        });

        this.childViews = this.createCollection([
            this.mathInputView,
            this.actionsView
        ]);

        this.setTemplate({
            tag: 'form',
            attributes: {
                class: ['ck', 'ck-math-form'],
                tabindex: '-1'
            },
            children: this.childViews
        });
    }

    render() {
        super.render();
        submitHandler({ view: this });
    }

    focus() {
        this._mathfield?.focus();
    }

    reset() {
        if (this._mathfield) {
            this._mathfield.value = '';
            this._mathfield.dispatchEvent(new Event('input'));
        }
    }

    setValue(latex) {
        if (this._mathfield && latex !== undefined && latex !== null) {
            this._mathfield.value = latex;
            this._mathfield.dispatchEvent(new Event('input'));
        }
    }

    getValue() {
        const latexStr = this._mathfield?.value || '';

        let html = '';
        try {
            html = katex.renderToString(latexStr, {
                throwOnError: false,
                displayMode: true,
            });
        } catch (error) {
            console.error('Ошибка KaTeX:', error);
            html = `<span style="color: red;">Ошибка: ${error.message}</span>`;
        }

        return {
            latex: latexStr,
            html: html
        };
    }

    _createMathInputView(locale) {
        const contentView = new View(locale);

        contentView.setTemplate({
            tag: 'div',
            attributes: {
                class: ['math-input-container']
            },
            children: [
                {
                    tag: 'div',
                    attributes: { class: ['math-tabs'] }
                },
                {
                    tag: 'div',
                    attributes: { class: ['math-toolbar'] }
                },
                {
                    tag: 'span',
                    attributes: { class: ['mathfield'] }
                }
            ]
        });

        contentView.render();

        // Создаём mathfield
        const mf = new MathfieldElement();
        const mathfieldSpan = contentView.element.querySelector('.mathfield');
        if (mathfieldSpan) {
            mathfieldSpan.appendChild(mf);
        }

        mf.addEventListener('mount', () => {
            mf.style.fontSize = '20px';
            mf.style.minWidth = '100%';
            mf.style.width = '100%';
            mf.defaultMode = 'math';
            mf.menuItems = [];
        });

        // Отключаем виртуальную клавиатуру
        mf.mathVirtualKeyboardPolicy = 'manual';
        if (window.mathVirtualKeyboard) {
            window.mathVirtualKeyboard.container = null;
        }

        this._mathfield = mf;

        const tabsEl = contentView.element.querySelector('.math-tabs');
        const toolbarEl = contentView.element.querySelector('.math-toolbar');

        if (tabsEl && toolbarEl) {
            this._buildTabs(tabsEl, toolbarEl, mf);
        }

        return contentView;
    }

    // Строим табы + переключаем содержимое панели
    _buildTabs(tabsEl, toolbarEl, mathfield) {
        // Функция отрисовки кнопок одной категории в панель
        const renderCategory = (category) => {
            toolbarEl.innerHTML = '';
            category.buttons.forEach(item => {
                toolbarEl.appendChild(this._createToolbarButton(item, mathfield));
            });
        };

        // Создаём кнопки-табы
        MATH_CATEGORIES.forEach((category, index) => {
            const tab = document.createElement('button');
            tab.type = 'button';
            tab.className = 'math-tab';
            tab.textContent = category.title;
            tab.dataset.categoryId = category.id;

            // Не забираем фокус у mathfield
            tab.addEventListener('mousedown', (e) => e.preventDefault());

            tab.addEventListener('click', () => {
                // Снимаем выделение с остальных
                tabsEl.querySelectorAll('.math-tab').forEach(el => {
                    el.classList.toggle('is-active', el === tab);
                });
                renderCategory(category);
            });

            tabsEl.appendChild(tab);

            // Первая вкладка — активная по умолчанию
            if (index === 0) {
                tab.classList.add('is-active');
                renderCategory(category);
            }
        });
    }

    // Создание одной кнопки оператора
    _createToolbarButton(item, mathfield) {
        const btn = document.createElement('button');
        btn.type = 'button';
        btn.className = 'math-toolbar-btn';
        btn.title = item.title;
        btn.innerHTML = katex.renderToString(item.icon, {
            throwOnError: false,
            displayMode: true
        });

        // Чтобы кнопка не забирала фокус у mathfield
        btn.addEventListener('mousedown', (e) => e.preventDefault());

        btn.addEventListener('click', () => {
            if (!mathfield) return;

            mathfield.focus();

            try {
                mathfield.insert(item.latex, {
                    selectionMode: 'placeholder',
                    focus: true
                });
            } catch (err) {
                console.warn('MathLive insert error:', err);
            }
        });

        return btn;
    }
}