// matheditorediting.js - отвечает за хранение данных и логику работы с формулами
import { Plugin, Widget, toWidget, viewToModelPositionOutsideModelElement } from 'ckeditor5';
import MathEditorCommand from './matheditorcommand';
import katex from 'katex';

// Этот класс управляет тем, как формулы хранятся в редакторе и как отображаются
export default class MathEditorEditing extends Plugin {
    // Объявляем, что нам нужен плагин Widget - он даёт возможность создавать перетаскиваемые блоки
    static get requires() {
        return [ Widget ];
    }

    static get pluginName() {
        return 'MathEditorEditing';
    }

    init() {
        // Шаг 1: Определяем структуру данных для формул
        this._defineSchema();
        
        // Шаг 2: Настраиваем преобразование между моделью и HTML
        this._defineConverters();
        
        // Шаг 3: Настраиваем поведение курсора вокруг формул
        this._defineWidgetIntegration();

        // Регистрируем команду вставки, которую будет вызывать кнопка на панели инструментов
        this.editor.commands.add('insertMath', new MathEditorCommand(this.editor));
        
        // Настраиваем обработчики событий для связи с UI плагином
        this._setupEventHandlers();
        
        // Добавляем обработчик двойного клика
        this._setupDoubleClickHandler();
    }
    
    // Настраиваем обработчики событий для связи с UI плагином
    _setupEventHandlers() {
        // Обработчик для обновления формулы из UI
        this.editor.on('mathEditor:updateFormula', (event, data) => {
            // 🔑 Не даём обновить формулу в readonly
            if (this.editor.isReadOnly) return;
            
            this.updateFormula(data.modelElement, data.latex, data.html);
        });
    }
    
    // Метод для запроса редактирования формулы - вызывает событие, на которое подпишется UI
    requestEditFormula(modelElement, latex) {
        // Генерируем кастомное событие, которое перехватит UI плагин
        this.editor.fire('mathEditor:editFormula', {
            modelElement: modelElement,
            latex: latex
        });
    }
    
    // Метод для обновления формулы после редактирования
    updateFormula(modelElement, latex, html) {
        const editor = this.editor;
        
        editor.model.change(writer => {
            // Обновляем атрибуты существующего элемента модели
            writer.setAttribute('latex', latex, modelElement);
            writer.setAttribute('html', html, modelElement);
            
            // Пересоздаём элемент, чтобы виджет обновился
            const position = writer.createPositionBefore(modelElement);
            writer.remove(modelElement);
            writer.insert(modelElement, position);
        });
        
        // Дополнительно принудительно обновляем визуальное представление
        this._refreshViewRepresentation(modelElement, html);
    }
    
    // Принудительное обновление визуального представления виджета
    _refreshViewRepresentation(modelElement, html) {
        const editor = this.editor;
        const editingView = editor.editing.view;
        const mapper = editor.editing.mapper;
        
        // Находим соответствующий view элемент
        const viewElement = mapper.toViewElement(modelElement);
        
        if (viewElement) {
            editingView.change(writer => {
                // Находим внутренний элемент с классом math-content
                const mathContent = Array.from(viewElement.getChildren())
                    .find(child => child.hasClass('math-content'));
                
                if (mathContent) {
                    // Создаём новый raw элемент с обновлённым HTML
                    const newContent = writer.createRawElement('div', {
                        class: 'math-content'
                    }, (domElement) => {
                        domElement.innerHTML = html;
                    });
                    
                    // Заменяем старый контент новым
                    writer.insert(writer.createPositionAfter(mathContent), newContent);
                    writer.remove(mathContent);
                }
            });
        }
    }

    // Метод определяет, как формула будет храниться во внутренней модели редактора
    _defineSchema() {
        const schema = this.editor.model.schema;

        schema.register('mathBlock', {
            allowWhere: '$text',
            isObject: true,
            isInline: true,
            allowAttributes: ['latex', 'html']
        });
        
        schema.addChildCheck((context, childDefinition) => {
            if (childDefinition.name === 'mathBlock') {
                return true;
            }
        });
    }

    // Метод настраивает конвертеры
    _defineConverters() {
        const conversion = this.editor.conversion;

        // КОНВЕРТЕР 1: При сохранении документа
        conversion.for('dataDowncast').elementToElement({
            model: 'mathBlock',
            view: (modelElement, { writer }) => {
                const html = modelElement.getAttribute('html');
                const latex = modelElement.getAttribute('latex');

                return writer.createRawElement('span', {
                    class: 'math-block',
                    'data-latex': latex
                }, (domElement) => {
                    domElement.innerHTML = html;
                });
            }
        });

        // КОНВЕРТЕР 2: При редактировании
        conversion.for('editingDowncast').elementToElement({
            model: 'mathBlock',
            view: (modelElement, { writer }) => {
                const html = modelElement.getAttribute('html');
                const latex = modelElement.getAttribute('latex');
                
                const container = writer.createContainerElement('span', {
                    class: 'math-block math-widget',
                    'data-latex': latex,
                    'contenteditable': 'false'
                });
                
                const inner = writer.createRawElement('span', {
                    class: 'math-content'
                }, (domElement) => {
                    domElement.innerHTML = html;
                });
                
                writer.insert(writer.createPositionAt(container, 0), inner);
                
                return toWidget(container, writer, {
                    label: 'Математическая формула',
                    hasSelectionHandle: true,
                    isFocused: false
                });
            }
        });

        // КОНВЕРТЕР 3: При загрузке документа
       conversion.for('upcast').elementToElement({
            view: {
                name: 'span',
                classes: 'math-block'
            },
            model: (viewElement, { writer }) => {
                const latex = viewElement.getAttribute('data-latex') || '';

                // Генерируем HTML из latex через KaTeX — не полагаемся на то,
                // что парсер извлёк из вложенной KaTeX-разметки.
                let html = '';
                if (latex) {
                    try {
                        html = katex.renderToString(latex, {
                            throwOnError: false,
                            displayMode: true,
                            output: 'html'
                        });
                    } catch (e) {
                        console.warn('KaTeX upcast render error:', e);
                    }
                }

                return writer.createElement('mathBlock', {
                    latex: latex,
                    html: html
                });
            }
        });
    }
    
    // Метод настраивает поведение курсора
    _defineWidgetIntegration() {
        const editor = this.editor;
        
        editor.editing.mapper.on('viewToModelPosition', 
            viewToModelPositionOutsideModelElement(editor.model, viewElement => {
                return viewElement.hasClass && viewElement.hasClass('math-block');
            })
        );
    }
    
    // ОБРАБОТЧИК ДВОЙНОГО КЛИКА
    _setupDoubleClickHandler() {
        const editor = this.editor;
        
        // Простой и надёжный способ - через глобальный обработчик на body
        // с проверкой, что клик внутри редактора
        const handler = (event) => {
            // 🔑 Если редактор в режиме только для чтения — ничего не делаем
            if (editor.isReadOnly) return;

            // Находим формулу
            const mathBlock = event.target.closest('.math-block');
            
            if (!mathBlock) return;
            
            // Проверяем, что клик внутри редактора
            const domRoot = editor.editing.view.getDomRoot();
            if (!domRoot || !domRoot.contains(mathBlock)) return;
            
            // Проверяем что это двойной клик
            if (event.detail !== 2) return;
            
            // Получаем LaTeX код
            const latex = mathBlock.getAttribute('data-latex');
            if (!latex) return;
            
            // Предотвращаем стандартное поведение
            event.preventDefault();
            event.stopPropagation();
            
            // Пытаемся найти модель
            let modelElement = null;
            
            // Ищем view элемент через DOM
            if (editor.editing.view.domConverter && editor.editing.view.domConverter.mapDomToView) {
                const viewElement = editor.editing.view.domConverter.mapDomToView(mathBlock);
                if (viewElement) {
                    modelElement = editor.editing.mapper.toModelElement(viewElement);
                }
            }
            
            // Если модель не найдена, но LaTeX есть - всё равно открываем редактирование
            // В этом случае будет создана новая формула, а старая останется
            this.requestEditFormula(modelElement, latex);
        };
        
        // Добавляем обработчик на весь документ
        document.addEventListener('dblclick', handler);
        
        // Сохраняем для удаления
        this._doubleClickHandler = handler;
    }

    // Обновите destroy метод
    destroy() {
        if (this._doubleClickHandler) {
            document.removeEventListener('dblclick', this._doubleClickHandler);
        }
        super.destroy();
    }
}