// matheditormodal.js - модальное окно для формы ввода формулы
import { View } from 'ckeditor5';

export default class MathEditorModal extends View {
    constructor(locale) {
        super(locale);

        // Контейнер модалки создаём вручную, чтобы не возиться с шаблоном
        this._overlayElement = null;
        this._dialogElement = null;
        this._contentView = null;
        this._onEscHandler = null;
    }

    // Показать модалку с переданной формой
    show(contentView) {
        if (this._overlayElement) return; // уже открыта

        this._contentView = contentView;

        // --- Overlay ---
        const overlay = document.createElement('div');
        overlay.className = 'ck-math-modal-overlay';

        // --- Диалог ---
        const dialog = document.createElement('div');
        dialog.className = 'ck-math-modal-dialog';
        dialog.setAttribute('role', 'dialog');
        dialog.setAttribute('aria-modal', 'true');

        // --- Шапка с заголовком и кнопкой закрытия ---
        const header = document.createElement('div');
        header.className = 'ck-math-modal-header';

        const title = document.createElement('span');
        title.className = 'ck-math-modal-title';
        title.textContent = 'Редактор формул';

        const closeBtn = document.createElement('button');
        closeBtn.type = 'button';
        closeBtn.className = 'ck-math-modal-close';
        closeBtn.setAttribute('aria-label', 'Закрыть');
        closeBtn.innerHTML = '&times;';
        closeBtn.addEventListener('click', () => this.hide());

        header.append(title, closeBtn);

        // --- Тело модалки: сюда монтируем форму ---
        const body = document.createElement('div');
        body.className = 'ck-math-modal-body';

        dialog.append(header, body);
        overlay.append(dialog);
        document.body.append(overlay);

        // Вставляем форму в body
        contentView.render();
        body.append(contentView.element);

        this._overlayElement = overlay;
        this._dialogElement = dialog;

        // Закрытие по Esc
        this._onEscHandler = (evt) => {
            if (evt.key === 'Escape') {
                evt.preventDefault();
                this.hide();
            }
        };
        document.addEventListener('keydown', this._onEscHandler);

        // Закрытие кликом по overlay (но не по диалогу)
        overlay.addEventListener('mousedown', (evt) => {
            if (evt.target === overlay) {
                this.hide();
            }
        });

        // Анимация появления
        requestAnimationFrame(() => {
            overlay.classList.add('ck-math-modal-visible');
        });
    }

    // Спрятать модалку
    hide() {
        if (!this._overlayElement) return;

        const overlay = this._overlayElement;
        const contentView = this._contentView;

        overlay.classList.remove('ck-math-modal-visible');

        // Ждём окончания анимации и удаляем
        setTimeout(() => {
            if (overlay.parentNode) {
                overlay.parentNode.removeChild(overlay);
            }
            if (contentView && contentView.element && contentView.element.parentNode) {
                contentView.element.parentNode.removeChild(contentView.element);
            }
        }, 180);

        if (this._onEscHandler) {
            document.removeEventListener('keydown', this._onEscHandler);
            this._onEscHandler = null;
        }

        this._overlayElement = null;
        this._dialogElement = null;
        this._contentView = null;

        // Сообщаем наружу, что модалка закрыта
        this.fire('close');
    }

    isVisible() {
        return !!this._overlayElement;
    }

    destroy() {
        this.hide();
        super.destroy();
    }
}